{
 "command": "cat Makefile; ls services 2>/dev/null",
 "description": "Show Makefile and services directory"
}

{
 "command": "make test-fast 2>&1 | tail -40; echo \"---NOTIFIER---\"; cd services/notifier && python -m pytest --import-mode=importlib tests -q 2>&1 | tail -30",
 "description": "Run fast suite and notifier tests"
}

{
 "command": "cd /tmp/mte-mt-sandbox-region-be5wx4ho/ledgerline && cat tests/fxdata.py; grep -rn \"LEDGERLINE_FX_FIXTURES\" --exclude-dir=.git . ; find . -path ./.git -prune -o -iname \"*fx*\" -print -o -iname \"*rates*\" -print",
 "description": "Inspect FX fixture loader and env var references"
}

{
 "command": "cat docs/testing.md; ls tests/fixtures/fx; head -30 scripts/gen_fx_fixtures.py",
 "description": "Read testing docs and fixture generator"
}

{
 "mode": "filter",
 "query": "FX rates fixtures",
 "include_invalidated": true
}

{
 "command": "python scripts/gen_fx_fixtures.py && LEDGERLINE_FX_FIXTURES=tests/fixtures/fx make test-fast 2>&1 | tail -30; git status --short",
 "description": "Generate FX fixtures and rerun fast suite"
}

{
 "mode": "filter",
 "query": "PSP sandbox region payments integration tests"
}

{
 "pattern": "PSP_SANDBOX_REGION|sandbox",
 "path": "/tmp/mte-mt-sandbox-region-be5wx4ho/ledgerline",
